import { memo, useEffect, useMemo, useState } from 'react';
import { Background, BackgroundVariant, Handle, Position, ReactFlow, type Node, type NodeProps } from '@xyflow/react';
import './AgentFlow.css';

type StepStatus = 'pending' | 'running' | 'completed' | 'failed';
type AgentNodeData = { id: string; title: string; summary: string; amount: string; status: StepStatus };
type AgentNode = Node<AgentNodeData, 'agent'>;
type DemoEvent = { id: string; tool: string; summary: string };

// Hardcoded demo mirrors the LangGraph fanout → relations → gate → finance path,
// with tool boxes for adapters and agent steps already implemented.
const PROCESS = [
  {
    id: 'sources',
    title: 'Agent scraping website',
    summary: 'Public research sources fan out',
    amount: '4 tools',
    tools: ['PubMed', 'ClinicalTrials.gov', 'IR / RSS news', 'Web news'],
  },
  {
    id: 'cala',
    title: 'Cala response',
    summary: 'Healthcare intelligence retrieved',
    amount: '3 tools',
    tools: ['Cala healthcare query', 'Entity extraction', 'Source snapshot'],
  },
  {
    id: 'health',
    title: 'Healthcare updates',
    summary: 'Relations and relevance evaluated',
    amount: '3 tools',
    tools: ['Build relation pack', 'Healthcare gate', 'New signal check'],
  },
  {
    id: 'finance',
    title: 'Financial output',
    summary: 'Impact assessment and report',
    amount: '3 tools',
    tools: ['Cala finance query', 'Financial impact', 'Watch-list recommendation'],
  },
] as const;

const DEMO_EVENTS: DemoEvent[][] = [
  [
    { id: 'e-pubmed', tool: 'pubmed', summary: 'Fetched PubMed deltas' },
    { id: 'e-trials', tool: 'clinicaltrials', summary: 'Fetched ClinicalTrials.gov studies' },
    { id: 'e-news', tool: 'news', summary: 'Fetched IR / RSS items' },
    { id: 'e-web', tool: 'web_news', summary: 'Fetched Tavily web news snippets' },
  ],
  [
    { id: 'e-cala-h', tool: 'cala', summary: 'Cala healthcare snapshot stored' },
    { id: 'e-entities', tool: 'research', summary: 'Entities upserted from sources' },
    { id: 'e-snapshot', tool: 'snapshot', summary: 'Source snapshot ready for relations' },
  ],
  [
    { id: 'e-relations', tool: 'relations', summary: 'Relation pack built' },
    { id: 'e-gate', tool: 'healthcare_gate', summary: 'Fastino gate scored relevance' },
    { id: 'e-signal', tool: 'healthcare_gate', summary: 'New healthcare signal confirmed' },
  ],
  [
    { id: 'e-cala-f', tool: 'cala', summary: 'Cala finance snapshot stored' },
    { id: 'e-impact', tool: 'finance', summary: 'Financial impact assessed' },
    { id: 'e-watch', tool: 'finance', summary: 'Watch-list recommendation drafted' },
  ],
];

const DEMO_DELAYS_MS = [700, 1400, 1400, 1400, 1200] as const;

function CalaMark() {
  return (
    <svg className="agent-flow-cala-mark" viewBox="0 0 48 48" aria-label="Cala" role="img">
      <path d="M40 10C31 4 17 7 12 17c-4 8-1 17 6 21 7 4 17 2 22-4-8 3-16-1-17-8-1-7 6-13 17-16Z" fill="currentColor" />
    </svg>
  );
}

const AgentNodeCard = memo(({ data }: NodeProps<AgentNode>) => (
  <div className={`agent-flow-node is-${data.status}`}>
    <Handle type="target" position={Position.Left} className="agent-flow-handle" />
    <div className="agent-flow-trigger">
      <span className={`agent-flow-status is-${data.status} ${data.id === 'cala' ? 'is-cala' : ''}`}>
        {data.id === 'cala' ? <CalaMark /> : data.status === 'completed' ? '✓' : data.status === 'running' ? '•' : '·'}
      </span>
      <span className="agent-flow-copy">
        <strong>{data.title}</strong>
        <small>{data.summary}</small>
      </span>
      <span className="agent-flow-amount">{data.status === 'completed' ? 'done' : data.amount}</span>
    </div>
    <Handle type="source" position={Position.Right} className="agent-flow-handle" />
  </div>
));

const nodeTypes = { agent: AgentNodeCard };
const edges = PROCESS.slice(0, -1).map((item, index) => ({
  id: `edge-${item.id}`,
  source: item.id,
  target: PROCESS[index + 1].id,
  type: 'smoothstep',
  animated: true,
  style: { stroke: '#9fb2a4', strokeWidth: 1.5 },
}));

function statusesForTick(tick: number): StepStatus[] {
  if (tick <= 0) return PROCESS.map(() => 'pending');
  if (tick > PROCESS.length) return PROCESS.map(() => 'completed');
  return PROCESS.map((_, index) => {
    if (index < tick - 1) return 'completed';
    if (index === tick - 1) return 'running';
    return 'pending';
  });
}

function eventsForTick(tick: number): DemoEvent[] {
  if (tick <= 0) return [];
  const completedThrough = Math.min(tick - 1, DEMO_EVENTS.length);
  return DEMO_EVENTS.slice(0, completedThrough).flat();
}

export function AgentFlow({ onViewResults }: { companyId?: string; initialRun?: unknown; onViewResults?: () => void }) {
  const [tick, setTick] = useState(0);
  const [playing, setPlaying] = useState(false);
  const statuses = statusesForTick(tick);
  const events = eventsForTick(tick);
  const running = playing && tick > 0 && tick <= PROCESS.length;
  const complete = tick > PROCESS.length;

  const nodes = useMemo<AgentNode[]>(
    () => PROCESS.map((item, index) => ({
      id: item.id,
      type: 'agent',
      position: { x: index * 265, y: 55 },
      data: { ...item, status: statuses[index] },
    })),
    [statuses],
  );

  useEffect(() => {
    if (!playing) return;
    if (tick > PROCESS.length) {
      setPlaying(false);
      return;
    }
    const delay = DEMO_DELAYS_MS[Math.min(tick, DEMO_DELAYS_MS.length - 1)];
    const timer = setTimeout(() => setTick((value) => value + 1), delay);
    return () => clearTimeout(timer);
  }, [playing, tick]);

  const runDemo = () => {
    setTick(0);
    setPlaying(true);
    setTick(1);
  };

  return (
    <div className="agent-flow">
      <div className="agent-flow-heading">
        <span>Agent process</span>
        <button type="button" className="agent-flow-run" onClick={runDemo} disabled={running}>
          {running ? 'Running…' : complete ? 'Run again' : 'Run agent'}
        </button>
      </div>
      <ReactFlow
        nodes={nodes}
        edges={edges}
        nodeTypes={nodeTypes}
        defaultViewport={{ x: 30, y: 0, zoom: 1 }}
        nodesDraggable={false}
        nodesConnectable={false}
        panOnDrag={false}
        panOnScroll={false}
        zoomOnScroll={false}
        zoomOnPinch={false}
        zoomOnDoubleClick={false}
        preventScrolling
        proOptions={{ hideAttribution: true }}
      >
        <Background variant={BackgroundVariant.Dots} gap={24} size={1} color="#e1e7e2" />
      </ReactFlow>
      <div className="agent-flow-tools">
        {PROCESS.map((process, index) => (
          <div className={`agent-flow-tool-group is-${statuses[index]}`} key={process.id}>
            {statuses[index] === 'pending' ? (
              <span className="agent-flow-tools-empty">Tools appear while this step runs</span>
            ) : (
              process.tools.map((tool) => (
                <span className="agent-flow-tool" key={tool}>
                  <i />
                  {tool}
                  <b>{statuses[index] === 'running' ? 'running' : statuses[index] === 'failed' ? 'failed' : 'done'}</b>
                </span>
              ))
            )}
          </div>
        ))}
      </div>
      {events.length > 0 && (
        <div className="agent-flow-events">
          {events.slice(-4).map((event) => (
            <div key={event.id}>
              <span>{event.tool}</span>
              <small>{event.summary}</small>
            </div>
          ))}
        </div>
      )}
      {complete && (
        <button type="button" className="agent-flow-results" onClick={onViewResults}>
          View results <span>→</span>
        </button>
      )}
    </div>
  );
}

